def roster(n, seed='plannable'):
    return [str(uuid.uuid5(uuid.NAMESPACE_URL, '%s/%d' % (seed, i))) for i in range(n)]


def inventory(k, replicas=None, tenants=10000, base=195, per=1.85):
    r = k if replicas is None else replicas
    owned = -(-tenants // k)
    return {'slices': {'evaluator': k, 'realtime': k},
            'workloads': {'evaluator': {'replicas': r}, 'realtime': {'replicas': r}},
            'connectionBudget': {'evaluator': {'residentMax': owned, 'memoryRequestMiB': -(-int((base + per * owned) * 100) // 100)}}}


BUDGET = {'poolConnections': 403, 'transient': 60, 'superuserReserved': 3, 'clinicalReserved': 40, 'budget': 506, 'maxConnections': 506}


class Slices(unittest.TestCase):
    def test_bucket_matches_core(self):
        for tenant, ordinals in CORE_VECTORS:
            self.assertEqual([p.bucket(tenant, k) for k in range(1, 9)], ordinals, tenant)

    def test_bucket_refuses_noncanonical_ids(self):
        for bad in ('ABCDEF00-0000-0000-0000-000000000000', 'x', None):
            with self.assertRaises(p.Refused):
                p.bucket(bad, 2)


class Point(unittest.TestCase):
    def test_one_k_sets_both_roles_two_api_and_leaves_memory_to_the_binding(self):
        for k in range(1, 33):
            v = p.point(k)
            self.assertEqual(v['slices'], {'evaluator': k, 'realtime': min(k, 8)})
            self.assertEqual(v['apiReplicas'], 2)
            self.assertNotIn('evaluatorMemory', v, 'the binding default model applies')
            self.assertTrue(v['labMetrics']['enabled'])
        self.assertEqual(p.point(20, realtime_k=4)['slices'], {'evaluator': 20, 'realtime': 4})
        self.assertEqual(p.point(8, evaluator_memory={'perResidentMiB': 1.2})['evaluatorMemory'], {'perResidentMiB': 1.2})
        for bad in ({'baseMiB': 0}, {'perResidentMiB': -1}, {'other': 1}):
            with self.assertRaises(p.Refused):
                p.point(8, evaluator_memory=bad)

    def test_k_outside_1_to_32_refuses_and_realtime_keeps_1_to_8(self):
        for k in (0, 33, 2.0, '4'):
            with self.assertRaises(p.Refused):
                p.point(k)
        for realtime_k in (0, 9, 20):
            with self.assertRaises(p.Refused):
                p.point(20, realtime_k=realtime_k)
        with self.assertRaises(p.Refused):
            p.point(2, pools={'receiver': 2})


class Profile(unittest.TestCase):
    BASE = {'version': 1, 'kind': 'k8s-m7-workload-profile', 'name': 'b', 'basis': 'x',
            'history': {'mode': 'synthetic-history-2d-v1', 'anchorUnixMs': 1}, 'phases': {'workSeconds': 7200},
            'population': {'hotFactor': 1, 'provisionedTenants': 1000, 'ordinaryRosterTenants': 1000}}

    def test_tenants_and_fixture_are_parameters(self):
        base = copy.deepcopy(self.BASE)
        v = p.profile(base, tenants=10000, anchor_ms=1795300000000, work_seconds=14400)
        self.assertEqual(base, self.BASE, 'base untouched')
        self.assertEqual(v['population']['provisionedTenants'], 10000)
        self.assertEqual(v['population']['ordinaryRosterTenants'], 10000)
        self.assertEqual(v['history'], {'mode': p.LOOPING_2D, 'anchorUnixMs': 1795300000000})
        self.assertEqual(v['name'], 'n10000-looping-2d-v1')
        self.assertEqual(p.profile(base, tenants=10, history_mode='synthetic-history-2d-v1')['history']['mode'], 'synthetic-history-2d-v1')

    def test_bad_fixture_or_count_refuses(self):
        for kwargs in ({'tenants': 0}, {'tenants': 10, 'history_mode': 'looping'}, {'tenants': 10, 'history_mode': None}):
            with self.assertRaises(p.Refused):
                p.profile(self.BASE, **kwargs)


class Ownership(unittest.TestCase):
    def test_every_tenant_owned_exactly_once_at_k_1_2_4_8(self):
        ids = roster(10000)
        for k in (1, 2, 4, 8):
            v = p.ownership(ids, inventory(k))
            for role in p.SLICED:
                self.assertEqual(sum(v[role]['perOrdinal']), 10000)
                self.assertEqual(len(v[role]['perOrdinal']), k)
                self.assertTrue(all(n > 0 for n in v[role]['perOrdinal']))
            self.assertEqual(v['residentMax'], -(-10000 // k))

    def test_red_a_k_that_leaves_a_tenant_unowned_fails(self):
        ids = roster(100)
        with self.assertRaises(p.Refused) as e:
            p.ownership(ids, inventory(4), live={'evaluator': [0, 1, 2]})
        self.assertEqual(str(e.exception), 'K8S_PLAN_TENANT_UNOWNED_EVALUATOR')
        with self.assertRaises(p.Refused) as e:
            p.ownership(ids, inventory(4, replicas=3))
        self.assertEqual(str(e.exception), 'K8S_PLAN_REPLICAS_NOT_K_EVALUATOR')
        with self.assertRaises(p.Refused):
            p.ownership(ids + ids[:1], inventory(2))

    def test_resident_shortfall_is_reported(self):
        v = p.ownership(roster(1001), inventory(8, tenants=1001))
        self.assertEqual(v['residentShortfall'], max(0, v['evaluator']['maxOwned'] - 126))


class CaseReadback(unittest.TestCase):
    def test_readback_selects_each_point_archive_and_query_bookend(self):
        class Server:
            def __init__(self, archive):
                self.archive = archive

            def query(self, expression, when):
                queries.add((self.archive.name, when))
                return []

            def close(self):
                pass

        with tempfile.TemporaryDirectory() as temp:
            case = Path(temp)
            points = ['small', 'larger', 'unfinished']
            (case/'lifecycle-input.json').write_text(json.dumps({'loadPoints': points}))
            (case/'inventory.json').write_text(json.dumps({'connectionBudget': {'poolConnections': 10}}))
            command = [sys.executable, '-B', p.__file__, 'readback', case]
            cli = json.loads(subprocess.check_output(command))
            self.assertEqual([row['pointId'] for row in cli['points']], points)
            self.assertTrue(all(row['connections']['verdict'] == 'UNMEASURED' for row in cli['points']))
            for name, start, end in [('small', 10, 20), ('larger', 25, 35)]:
                load = case/'runtime/points'/name/'packet/load'
                load.mkdir(parents=True)
                (load/'window.json').write_text(json.dumps({'loadStartedAt': start, 'loadEndedAt': end}))
                (load/'metrics-snapshot.json').write_text(json.dumps({'verdict': 'OBSERVED', 'file': name + '.tar'}))
            queries = set()
            readback = p.case_readback(case, server_factory=Server)
            self.assertEqual(queries, {('small.tar', 20), ('larger.tar', 35)})
            self.assertEqual(readback['points'][2]['connections']['verdict'], 'UNMEASURED')


class Connections(unittest.TestCase):
    def fig(self, peak, setting=506):
        return {'clientBackendsPeak': [{'labels': {}, 'value': peak}], 'maxConnectionsSetting': [{'labels': {}, 'value': setting}],
                'byApplicationPeak': [{'labels': {'application_name': 'nightscout-evaluator-preview'}, 'value': 32}]}

    def test_verdicts_against_the_rendered_budget(self):
        self.assertEqual(p.connections(self.fig(300), BUDGET)['verdict'], 'PASS')
        self.assertEqual(p.connections(self.fig(463), BUDGET)['verdict'], 'PASS')
        self.assertEqual(p.connections(self.fig(464), BUDGET)['verdict'], 'OVER_PLAN')
        self.assertEqual(p.connections(self.fig(503), BUDGET)['verdict'], 'FAIL')
        self.assertEqual(p.connections({}, BUDGET)['verdict'], 'UNMEASURED')
        v = p.connections(self.fig(300, setting=140), BUDGET)
        self.assertFalse(v['settingMatches'])
        self.assertEqual(v['peakByApplication'], {'nightscout-evaluator-preview': 32})


class Warmup(unittest.TestCase):
    def test_no_resident_gauge_is_no_instrument_never_green(self):
        v = p.warmup({'podStart': {'evaluator-0': 100.0}, 'residents': {}}, {'evaluator-0': 5}, step_s=15)
        self.assertEqual(v['verdict'], 'NO-INSTRUMENT')
        self.assertEqual(p.warmup({}, {}, step_s=15)['verdict'], 'UNMEASURED')

    def test_pod_start_to_all_owned_and_first_alarm(self):
        series = {'podStart': {'evaluator-0': 100.0, 'evaluator-1': 110.0},
                  'residents': {'evaluator-0': [(115, 2), (130, 5), (145, 5)], 'evaluator-1': [(125, 6), (160, 7)]}}
        v = p.warmup(series, {'evaluator-0': 5, 'evaluator-1': 7}, first_alarm_ms=140000, step_s=15)
        self.assertEqual(v['verdict'], 'OBSERVED')
        self.assertEqual(v['pods']['evaluator-0']['allEvaluatedSeconds'], 30)
        self.assertEqual(v['pods']['evaluator-1']['allEvaluatedSeconds'], 50)
        self.assertEqual(v['pods']['evaluator-0']['firstAlarmSeconds'], 40)
        self.assertEqual(v['maxAllEvaluatedSeconds'], 50)
        partial = p.warmup(series, {'evaluator-0': 6, 'evaluator-1': 7}, step_s=15)
        self.assertEqual(partial['verdict'], 'INCOMPLETE')
        self.assertIsNone(partial['maxAllEvaluatedSeconds'])

    def test_first_alarm_query_is_read_only_and_bounded(self):
        q = p.first_alarm_query('nsdemo_notifications', 1795300000000)
        self.assertTrue(q.startswith('SELECT ') and 'created_at >= 1795300000000' in q)
        for bad in ('x; DROP', 'A'):
            with self.assertRaises(p.Refused):
                p.first_alarm_query(bad, 1)


class DeployBinding(unittest.TestCase):
    def test_the_deploy_tree_is_named_explicitly_and_never_guessed(self):
        for source in ({}, {'NS_DEPLOY_BINDING': ''}, {'NS_DEPLOY_BINDING': 'relative/deploy'}):
            with self.assertRaisesRegex(p.Refused, 'K8S_PLAN_DEPLOY_BINDING_REQUIRED'):
                p.deploy_binding(source)
        with tempfile.TemporaryDirectory() as d:
            with self.assertRaisesRegex(p.Refused, 'K8S_PLAN_DEPLOY_BINDING_INVALID'):
                p.deploy_binding({'NS_DEPLOY_BINDING': d})
            lib = Path(d)/'bindings/kubernetes/lib/ns'
            lib.mkdir(parents=True)
            (lib/'connection-budget.libsonnet').write_text('{}')
            self.assertEqual(p.deploy_binding({'NS_DEPLOY_BINDING': d}), Path(d))
        # No workstation path is written into the harness as a fallback.
        for name in ('plannable.py', 'test_plannable.py'):
            self.assertNotIn('/worktrees/' + 'deploy/', (Path(__file__).parent/name).read_text(), name)


class Rendered(unittest.TestCase):
    """The harness's one K input through the deploy render: budget, memory and ownership agree.

    NS_DEPLOY_BINDING names the deploy tree. Unset or not a deploy tree refuses (an error, not a skip):
    these checks have no meaning against a guessed binding."""

    @classmethod
    def setUpClass(cls):
        cls.deploy = p.deploy_binding()
        if not shutil.which('tk'):
            raise unittest.SkipTest('tk required')

    def render(self, extra):
        lib = self.deploy/'bindings/kubernetes'
        base = json.loads((lib/'environments/synthetic/inputs.json').read_text())
        with tempfile.TemporaryDirectory() as d:
            env = Path(d)/'environments/x'
            env.mkdir(parents=True)
            (Path(d)/'jsonnetfile.json').write_text('{"version":1,"dependencies":[],"legacyImports":true}')
            shutil.copy(lib/'environments/synthetic/spec.json', env/'spec.json')
            (env/'main.jsonnet').write_text('local ns=import %s; local x=ns.new(std.mergePatch(%s,%s)); {inventory: {i: x.inventory}}'
                                            % (json.dumps(str(lib/'lib/ns/nightscout.libsonnet')), json.dumps(base), json.dumps(extra)))
            out = subprocess.run(['tk', 'eval', 'environments/x'], cwd=d, capture_output=True, text=True, timeout=120)
            self.assertEqual(out.returncode, 0, out.stderr)
            return json.loads(out.stdout)['inventory']['i']

    def test_k_20_renders_with_realtime_8_and_the_binding_memory_model(self):
        inv = self.render({**p.point(20), 'tenantCount': 10000})
        self.assertEqual(inv['slices'], {'evaluator': 20, 'realtime': 8})
        ev = inv['connectionBudget']['evaluator']
        self.assertEqual((ev['residentMax'], ev['memoryRequestMiB'], ev['heapMiB']), (599, 3519, 5279))
        own = p.ownership(roster(10000), inv)
        self.assertEqual(sum(own['evaluator']['perOrdinal']), 10000)
        self.assertLessEqual(max(own['evaluator']['perOrdinal']), 599)

    def test_k_9_16_20_32_budget_memory_and_ownership(self):
        # Evaluator K above 8 with realtime at its bound of 8 and two api: 322 + 23 x K connections.
        ids = roster(10000)
        expected = {9: (529, 1253, 5454), 16: (690, 734, 3918), 20: (782, 599, 3519), 32: (1058, 391, 2903)}
        for k, (budget, resident, memory) in expected.items():
            inv = self.render({**p.point(k), 'tenantCount': 10000})
            self.assertEqual(inv['slices'], {'evaluator': k, 'realtime': 8})
            self.assertEqual(budget, 322 + 23 * k)
            self.assertEqual((inv['connectionBudget']['budget'], inv['connectionBudget']['maxConnections']), (budget, budget))
            ev = inv['connectionBudget']['evaluator']
            self.assertEqual((ev['residentMax'], ev['memoryRequestMiB']), (resident, memory))
            self.assertGreaterEqual(ev['heapMiB'], ev['memoryRequestMiB'])
            own = p.ownership(ids, inv)
            self.assertEqual(sum(own['evaluator']['perOrdinal']), 10000)
            self.assertEqual(len(own['evaluator']['perOrdinal']), k)
            self.assertTrue(all(n > 0 for n in own['evaluator']['perOrdinal']))
            self.assertLessEqual(max(own['evaluator']['perOrdinal']), resident)
            # A Pod missing from the live set leaves its tenants unowned: refused, not measured.
            with self.assertRaisesRegex(p.Refused, 'TENANT_UNOWNED_EVALUATOR'):
                p.ownership(ids, inv, live={'evaluator': range(k - 1)})

    def test_k_1_2_4_8_budget_memory_and_ownership(self):
        ids = roster(10000)
        expected = {1: 205, 2: 248, 4: 334, 8: 506}
        for k in (1, 2, 4, 8):
            inv = self.render({**p.point(k), 'tenantCount': 10000})
            self.assertEqual(inv['connectionBudget']['budget'], expected[k])
            self.assertEqual(inv['connectionBudget']['maxConnections'], expected[k])
            ev = inv['connectionBudget']['evaluator']
            self.assertGreaterEqual(ev['residentMax'], -(-10000 // k))
            self.assertEqual(ev['memoryRequestMiB'], int(-(-(1745 + 2.96 * ev['residentMax']) // 1)))
            container = next(c for c in inv['workloads']['evaluator']['containers'] if c['name'] == 'evaluator')
            self.assertEqual(container['command'][1], '--max-old-space-size=%d' % ev['heapMiB'])
            self.assertEqual(container['resources']['requests']['memory'], '%dMi' % ev['memoryRequestMiB'])
            self.assertNotIn('limits', container['resources'])
            own = p.ownership(ids, inv)
            self.assertEqual(sum(own['evaluator']['perOrdinal']), 10000)


if __name__ == '__main__':
    unittest.main()
